package main
import("crypto/hmac";"crypto/sha256";"encoding/base64";"encoding/json";"os";"strings";"time";utils "github.com/Tencent/WeKnora/internal/utils")
func main(){os.Setenv("JWT_SECRET","oidc-migration-state-secret");now:=time.Now();out:=map[string]any{"now_second":now.Unix(),"now_nano":now.Nanosecond()};sign:=[]map[string]any{};for _,nonce:=range []string{"nonce"," a ","中文","<&>","😀"," ",""," "," "}{for _,redirect:=range []string{"https://app.example/callback","https://app.example/a?x=<>&y=中文"," / ",""," "}{payload:=&utils.OIDCStatePayload{Nonce:nonce,RedirectURI:redirect,IssuedAt:1700000000};token,err:=utils.SignOIDCState(payload);row:=map[string]any{"payload":payload,"clock":now.Unix()};if err!=nil{row["error"]=err.Error()}else{row["state"]=token};sign=append(sign,row)}};for _,iat:=range []int64{0,-1,1,9223372036854775807,-9223372036854775808}{p:=&utils.OIDCStatePayload{Nonce:"nonce",RedirectURI:"https://app.example",IssuedAt:iat};token,err:=utils.SignOIDCState(p);row:=map[string]any{"payload":p,"clock":now.Unix()};if iat==0{row["clock"]=p.IssuedAt};if err!=nil{row["error"]=err.Error()}else{row["state"]=token};sign=append(sign,row)};_,err:=utils.SignOIDCState(nil);sign=append(sign,map[string]any{"payload":nil,"error":err.Error(),"clock":now.Unix()});out["sign"]=sign
verify:=[]map[string]any{};base:=map[string]any{"nonce":"nonce","redirect_uri":"https://app.example/callback","iat":now.Unix()};raws:=[]string{};for _,offset:=range []int64{-601,-600,-599,-1,0,1,59,60,61,9223372036854775000,-9223372036854775000}{p:=map[string]any{"nonce":"nonce","redirect_uri":"https://app.example/callback","iat":now.Unix()};if offset>9223372036000000000||offset< -9223372036000000000{p["iat"]=offset}else{p["iat"]=now.Unix()+offset};b,_:=json.Marshal(p);raws=append(raws,signed(b))};for _,raw:=range []string{`{}`,`null`,`[]`,`"text"`,`{"nonce":"nonce","redirect_uri":"/","iat":0}`,`{"nonce":"nonce","redirect_uri":" ","iat":NOW}`,`{"nonce":"nonce","redirect_uri":"/","iat":"NOW"}`,`{"nonce":"nonce","redirect_uri":"/","iat":1.0}`,`{"nonce":1,"redirect_uri":"/","iat":NOW}`,`{"nonce":1,"nonce":"nonce","redirect_uri":"/","iat":NOW}`,`{"nonce":"nonce","nonce":null,"redirect_uri":"/","iat":NOW}`,`{"nonce":"nonce","REDIRECT_URI":"/","IAT":NOW}`,`{"nonce":"nonce","redirect_uri":"/","iat":NOW,"unknown":true}`,`{"nonce":"nonce","redirect_uri":"/","iat":9223372036854775808}`,`{"nonce":"nonce","redirect_uri":"/","iat":NOW} {}`,`{`,`{"nonce":"\ud800","redirect_uri":"/","iat":NOW}`} {raw=strings.ReplaceAll(raw,"NOW",timeNumber(now.Unix()));raws=append(raws,signed([]byte(raw)))};goodBytes,_:=json.Marshal(base);good:=signed(goodBytes);parts:=strings.Split(good,".");raws=append(raws,"", ".", "abc", "a.b.c", "A.AAAA", "%.AAAA", "中文.AAAA", "AAAA.%", "AAAA.中文",parts[0]+"=."+parts[1],parts[0]+"."+parts[1]+"=",parts[0]+".AAAA",parts[0]+"."+parts[1][:len(parts[1])-1],"  "+good+" 　",parts[0][0:3]+"\n"+parts[0][3:]+"."+parts[1][0:5]+"\r\n"+parts[1][5:]);for _,token:=range raws{payload,err:=utils.VerifyOIDCState(token);row:=map[string]any{"state":token};if err!=nil{row["error"]=err.Error()}else{row["payload"]=payload};verify=append(verify,row)};out["verify"]=verify;json.NewEncoder(os.Stdout).Encode(out)}
func signed(raw []byte)string{mac:=hmac.New(sha256.New,[]byte("oidc-migration-state-secret"));mac.Write(raw);return base64.RawURLEncoding.EncodeToString(raw)+"."+base64.RawURLEncoding.EncodeToString(mac.Sum(nil))}
func timeNumber(i int64)string{b,_:=json.Marshal(i);return string(b)}
